      "মরাও নয় জেদাও নয়,",
      "আধামরা!",
      "\"উল্লো লায়োরি কুলো ব'",
      "ন'আন্ মাধাত্ দি, জুমোরান্ ব'।\"",
      "--- মর বুক্ চুচ্যাং তাগল' ঘেই!",
      "মরে কছ্ বিদেশ্যা,.....",
      "ইচ্চা-কিল্যা ম'জাগাত্ য়েই।",
      "পিঠ্ আর ন' লামিম,",
      "হক্ তাগল্ দেগিনেই!",
      "__STANZA__",
      "ইয়ানি কি কারবার,",
      "চোগেদি ন' দিখ্যা!",
      "মুরিলে মুরিম্ বুক্ দি!",
      "ন' মুরিম্ পিঠদ্যা!",
      "দুগে আর ন' কারের ভর,",
      "জুলি ন' উধিম্ কিত্তা!!!",
      "__STANZA__",
