      "__STANZA__",
      "দাধা যিয়ে বাজারত্,",
      "বাবা যিয়ে জুমকাবা।",
      "ভুজি যিয়ে কুয়োগাঙত্,",
      "মামাহ্ যিয়ে তোনতোগা।",
